  function userMessageSteerHtml(text, notification, compactCardHtml, ev) {
    // Transcript events are already delivered; only unsent echoes may steer.
    if (ev) return '';
    const isCodex = sharedState.currentSession && sharedState.currentSession.source === 'codex';
    // Render the button for every devin-cli user message like codex does —
    // capability is a live signal (devinTurnSteerable/syncUserMessageSteerButtons
    // keep it hidden until liveStatus says acp+running), and gating render on
    // it meant a late-arriving status could never reveal the button.
    const isDevin = sharedState.currentSession && sharedState.currentSession.source === 'devin-cli';
    if (!isCodex && !isDevin) return '';
    if (notification || compactCardHtml || !String(text || '').trim()) return '';
    const steerable = isCodex ? codexTurnSteerable() : devinTurnSteerable();
    const engine = isCodex ? 'Codex' : 'Devin';
    const title = steerable
      ? 'Steer ' + engine + ' with this message'
      : 'No running ' + engine + ' turn can be steered from CCC; use Send to resume or follow up';
    const inactiveAttrs = steerable ? '' : ' hidden disabled aria-hidden="true"';
    const originId = (ev && ((ev.attribution && ev.attribution.message_id) || (ev.peer && ev.peer.msg_id))) || '';
    return '<button type="button" class="user-message-steer" data-steer-user-message'
      + (originId ? ' data-steer-origin-msg-id="' + (0, sharedState.escapeAttr)(originId) + '"' : '')
      + inactiveAttrs + ' title="' + (0, sharedState.escapeAttr)(title)
      + '" aria-label="Steer ' + (0, sharedState.escapeAttr)(engine) + ' with this message">Steer</button>';
  }

