    sharedState._swipeRecent = [id].concat(sharedState._swipeRecent.filter(x => x !== id)).slice(0, sharedState.SWIPE_RECENT_CAP);
    try { localStorage.setItem(sharedState.SWIPE_RECENT_KEY, JSON.stringify(sharedState._swipeRecent)); } catch (_) {}
