        const retryPid = card.spawn_pid || String(card.id || '').replace(/^spawning-/, '');
        const retryCwd = card.spawn_cwd || card.repo_path || card.folder_path || card.cwd || '';
        const retryEngine = card.source === 'interactive' ? 'claude' : card.source;
