    const pid = card.spawn_pid || String(card.id || '').replace(/^spawning-/, '');
    if (!pid || !card.id) return false;
    const endpoint = card.spawn_endpoint || '/api/sessions/spawn';
    card.spawn_failed = false;
    card.spawn_error = '';
