  function _ensureEngineSvgSprite() {
    if (sharedState._engineSvgSpriteReady) return true;
    if (typeof document === 'undefined' || !document || !document.body) return false;
    if (document.getElementById(sharedState._ENGINE_SVG_SPRITE_ID)) {
      sharedState._engineSvgSpriteReady = true;
      return true;
    }
    const symbols = sharedState._ENGINE_SVG_KEYS.concat(['default']).map((key) => {
      const inline = _engineSvgInline(key === 'default' ? '' : key);
      return inline
        .replace('<svg class="conv-session-svg"', '<symbol id="' + _engineSvgSymbolId(key) + '"')
        .replace('</svg>', '</symbol>');
    }).join('');
    // Not display:none: WebKit will not instantiate <use> targets that live
    // inside a display:none subtree. Zero-size and clipped is the safe form.
    const host = document.createElement('div');
    host.innerHTML = '<svg id="' + sharedState._ENGINE_SVG_SPRITE_ID + '" aria-hidden="true" focusable="false"'
      + ' style="position:absolute;width:0;height:0;overflow:hidden">' + symbols + '</svg>';
    document.body.insertBefore(host.firstChild, document.body.firstChild);
    sharedState._engineSvgSpriteReady = true;
    return true;
  }

