  function chasePendingSpawn(pid, opts) {
    const card = sharedState.pendingSpawns.get(pid) || Array.from(sharedState.pendingSpawns.values())
      .find(c => c && (c.id === 'spawning-' + pid || (opts?.sessionId && c.expected_session_id === opts.sessionId)));
    // The selected Antigravity pane already polls its own process for the
    // native ID. Background launches still reconcile via the ordinary list.
    if (card?.source === 'antigravity' && sharedState.currentConversation === card.id) return;
    if (card?.source === 'codex' && card._landedResolved) return;
    const deadline = Date.now() + ((opts && opts.timeoutMs) || 45000);
    const every = (opts && opts.intervalMs) || 1200;
    const sid = (opts && opts.sessionId) || null;
    let ticks = 0;
    let landed = false;
    (function tick() {
      // `adoptPendingSpawnPid` re-keys a continuation from its optimistic
      // temporary id to the server pid. Its card intentionally retains the
      // temporary DOM id until reconciliation, so check both representations.
      if (!_pendingSpawnStillWaiting(pid, 'spawning-' + pid)) return;
      if (Date.now() > deadline) return;        // give up quietly; the normal
                                                // poll and the not-acknowledged
                                                // path still cover this
      ticks += 1;
      // Landing is when the ENGINE has the session. The row still has to
      // survive a list build and a render, so keep going until the pending
      // placeholder is actually reconciled above - just at a slower cadence,
      // since each of these is the expensive full refresh.
      const again = (delay) => setTimeout(tick, delay || every);
      if (landed || !sid) { (0, hostServices.refreshConversationList)(); again(landed ? 2500 : 0); return; }
      fetch('/api/session/landed?session_id=' + encodeURIComponent(sid), { cache: 'no-store' })
        .then(d => d.json())
        .then(d => {
          if (d && d.landed) { landed = true; (0, hostServices.refreshConversationList)(); again(2500); return; }
          // Not landed yet. Still refresh occasionally in case this engine is
          // one the probe cannot speak for, so a false negative cannot strand
          // the row - but every 5th tick, not every tick.
          if (ticks % 5 === 0) (0, hostServices.refreshConversationList)();
          again();
        })
        .catch(() => { (0, hostServices.refreshConversationList)(); again(); });
    })();
  }

